style.css:
@-moz-document domain("roblox.com") {
.container-main, .content, body {
        /* Paste your i.pinimg.com link inside the quotes below */
        background-image: url("https://i.pinimg.com/736x/96/59/1b/96591b14803c74d04911e2bc63620a2a.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Keep this part to make the Roblox boxes transparent so you can see Five */
    .section-content, .rbx-tabs-horizontal, .content {
        background-color: rgba(0, 0, 0, 0.5) !important;
    }
}
